from contextlib import contextmanager
from inspect import stack
from logging import Logger
from os import path

from taf.sbts.oam.coam.admin import admin as taf_admin

from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import SERVER_HOST

logger = Logger("LC")


def _collect_admin_scfc(log_file):
    # type: (str) -> None
    """
    Use Admin to collect SCFC file from enb.

    :param log_file: string containing the destination where to save SCFC file and its name
    """
    admin = taf_admin()
    try:
        admin.setup_admin()
        admin.collect_scf(target_file_name=log_file)
    except Exception as exc:
        logger.error(
            "Could not collect SCFC file. Exception [{}] caught [{}]]".format(type(exc).__name__, exc), exc_info=True
        )
    finally:
        admin.teardown_admin()


def start():
    """Method does nothing, this plugin does not require activation."""
    logger.info("Inside {} start".format(path.basename(__file__)))


def stop(log_dir):
    # type: (str) -> None
    """
    Method should collect and store SCFC file from enb

    :param log_dir: string containing the destination where to save SCFC file
    """
    logger.info("Inside {} before stop".format(path.basename(__file__)))
    log_file = path.join(log_dir, "scfc_{}.xml".format(SERVER_HOST))
    _collect_admin_scfc(log_file)
    logger.info("Inside {} after stop".format(path.basename(__file__)))


@contextmanager
def scfc(log_host, log_port, **kwargs):
    # type: (str, int, dict) -> Iterator[None]
    """
    Plugin for collecting SCFC file from enb. When it starts it does nothing but waits
    for stop action. Then it downloads file from enb and saves it at the destatnation
    provided by the user.

    :param log_host: IP address of logger host
    :param log_port: port of logger host
    """
    global logger
    logger = get_net_logger(log_host, log_port, "{}_{}".format(stack(0)[0][3], SERVER_HOST))
    log_dir = kwargs.pop("log_dir")
    try:
        start()
        yield
    finally:
        stop(log_dir)
